 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The two sequences are encoded on the bottom row, separated by zeros.
    nz = [(c, grid[-1][c]) for c in range(w) if grid[-1][c]]
    # contiguous runs of nonzero values are the patterns
    runs = []
    run = []
    for c, v in nz:
        if run and c != run[-1][0] + 1:
            runs.append([v0 for _, v0 in run]); run = []
        run.append((c, v))
    if run: runs.append([v for _, v in run])
    for r in range(h - 1):
        for c in range(w):
            v = grid[r][c]
            if not v: continue
            for pattern in runs:
                if v not in pattern: continue
                i = pattern.index(v)
                start = c - i
                for j, color in enumerate(pattern):
                    x = start + j
                    if 0 <= x < w:
                        out[r][x] = color
                break
    return out
