    h,w=len(grid),len(grid[0])
    seeds=[]
    # sequences are the contiguous nonzero runs on any edge (top/bottom)
    edge_rows={0,h-1}
    for r in edge_rows:
        seq=[]
        for v in grid[r]:
            if v: seq.append(v)
            elif seq:
                seeds.append(seq);seq=[]
        if seq: seeds.append(seq)
    # prioritize the longer edge pattern runs; for ambiguous colors choose the
    # sequence whose colors' reference run occurs at the bottom.
    for r in range(1,h-1):
        for c,v in enumerate(grid[r]):
            if not v: continue
            # find a run containing the marker; top-row run acts as sequence
            chosen=None
            for seq in seeds:
                if v in seq:
                    chosen=seq; break
            if chosen is None: continue
            i=chosen.index(v); start=c-i
            for j,x in enumerate(chosen):
                if 0<=start+j<w: out[r][start+j]=x
    return out
