 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def runs(row):
        result, current = [], []
        for value in row:
            if value:
                current.append(value)
            elif current:
                result.append(current)
                current = []
        if current:
            result.append(current)
        return result

    # Edge runs serve as templates; each non-edge colored cell anchors a copy.
    templates = runs(grid[0]) + runs(grid[-1])
    for r in range(1, h - 1):
        for c, value in enumerate(grid[r]):
            if not value:
                continue
            template = next((seq for seq in templates if value in seq), None)
            if template is None:
                continue
            start = c - template.index(value)
            for offset, color in enumerate(template):
                x = start + offset
                if 0 <= x < w:
                    out[r][x] = color
    return out
